from PIL import Image, ImageFilter
import numpy as np, sys
sys.setrecursionlimit(10000)
im = Image.open('1.jpg').convert('L')
a = np.asarray(im).astype(float)
bg = np.asarray(im.filter(ImageFilter.GaussianBlur(60))).astype(float)
flat = a/(bg+1e-6)*140

def blobs(x0,x1,y0,y1,thr=118,minarea=150):
    reg = flat[y0:y1, x0:x1]
    mask = (reg < thr).astype(np.uint8)
    H,W = mask.shape
    seen = np.zeros_like(mask, bool)
    out=[]
    from collections import deque
    for yy in range(H):
        for xx in range(W):
            if mask[yy,xx] and not seen[yy,xx]:
                q=deque([(yy,xx)]); seen[yy,xx]=True; pts=[]
                while q:
                    cy,cx=q.popleft(); pts.append((cy,cx))
                    for dy,dx in ((1,0),(-1,0),(0,1),(0,-1)):
                        ny,nx=cy+dy,cx+dx
                        if 0<=ny<H and 0<=nx<W and mask[ny,nx] and not seen[ny,nx]:
                            seen[ny,nx]=True; q.append((ny,nx))
                if len(pts)>=minarea:
                    ys=[p[0] for p in pts]; xs=[p[1] for p in pts]
                    mean=reg[ys,xs].mean()
                    out.append((x0+min(xs), x0+max(xs), y0+min(ys), y0+max(ys), len(pts), round(mean)))
    return out

